INSERT INTO teachings (title, slug, excerpt, content, category, featured_image, status, is_featured, read_time_minutes) VALUES
('What Happens When the Drum Stops', 'what-happens-when-drum-stops', 'On silence, integration, and the work that happens after ceremony. The most profound transformations often occur in the days and weeks following a sacred ritual.', 'Most people are prepared for the ceremony itself. Few are prepared for what comes after — the dreams that shift, the emotions that surface, the memories that return. This is the sacred work of integration. When the drum stops, the real journey begins. The silence that follows ceremony is not empty; it is full of potential. In that space, the seeds planted during our work together begin to germinate. This is why we place such emphasis on post-ceremony integration at our retreats.', 'ceremony', '/shaman_drum.png', 'published', true, 15),
('On Choosing a Shaman', 'on-choosing-a-shaman', 'How to find the right practitioner for your journey. What questions to ask, what signs to look for, and how to trust your intuition.', 'Choosing a shamanic practitioner is one of the most important decisions you will make on your healing journey. Look for lineage, authenticity, and the feeling of being truly seen. A real shaman does not need to convince you — their presence will do the talking.', 'guide', '/abhay_img.png', 'published', false, 6),
('The Difference Between Healing and Fixing', 'healing-vs-fixing', 'Why transformation cannot be rushed, and the crucial distinction between quick fixes and deep healing.', 'In the modern world, we are conditioned to seek quick fixes. A pill for every problem, a technique for every challenge. But healing is not fixing. Fixing addresses symptoms; healing addresses the root. Fixing returns you to baseline; healing elevates you to a new level of being.', 'philosophy', '/sampo_gold_shield.png', 'published', false, 8);
